package com.garagedesk.service; import com.garagedesk.entity.*; import com.garagedesk.exception.*; import com.garagedesk.repo.*; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*;
@Service public class JobCardService{final JobCardRepository jobs;final VehicleRepository vs;final MechanicRepository ms;final ServiceBayRepository bs;final BillRepository bills;public JobCardService(JobCardRepository j,VehicleRepository v,MechanicRepository m,ServiceBayRepository b,BillRepository bi){jobs=j;vs=v;ms=m;bs=b;bills=bi;}public List<JobCard> all(){return jobs.findAll();}public JobCard get(Long id){return jobs.findById(id).orElseThrow(()->new ResourceNotFoundException("Job card not found: "+id));}
public JobCard create(Long vid,Long mid,Long bid,String svc,String complaint,String work,LocalDateTime start,LocalDateTime end){if(start==null||end==null||!end.isAfter(start))throw new ConflictException("End time must be after start time");Vehicle v=vs.findById(vid).orElseThrow(()->new ResourceNotFoundException("Vehicle not found"));Mechanic m=ms.findById(mid).orElseThrow(()->new ResourceNotFoundException("Mechanic not found"));ServiceBay b=bs.findById(bid).orElseThrow(()->new ResourceNotFoundException("Bay not found"));if(!m.isAvailable())throw new ConflictException("Mechanic is unavailable");if(!b.isActive())throw new ConflictException("Bay is inactive");boolean bc=jobs.findByBay_IdAndStatusNot(bid,JobStatus.COMPLETED).stream().filter(x->x.getStatus()!=JobStatus.CANCELLED).anyMatch(x->x.getScheduledStart().isBefore(end)&&x.getScheduledEnd().isAfter(start));if(bc)throw new ConflictException("Bay is already occupied during this time");boolean mc=jobs.findByMechanicIdAndScheduledStartLessThanAndScheduledEndGreaterThan(mid,end,start).stream().anyMatch(x->x.getStatus()!=JobStatus.COMPLETED&&x.getStatus()!=JobStatus.CANCELLED);if(mc)throw new ConflictException("Mechanic is already assigned during this time");JobCard j=new JobCard();j.setVehicle(v);j.setMechanic(m);j.setBay(b);j.setRequestedServices(svc);j.setCustomerComplaint(complaint);j.setWorkDescription(work);j.setScheduledStart(start);j.setScheduledEnd(end);return jobs.save(j);}
public JobCard status(Long id,JobStatus n){JobCard j=get(id);JobStatus c=j.getStatus();boolean ok=(c==JobStatus.WAITING&&n==JobStatus.IN_PROGRESS)||(c==JobStatus.IN_PROGRESS&&n==JobStatus.QUALITY_CHECK)||(c==JobStatus.QUALITY_CHECK&&n==JobStatus.COMPLETED)||(n==JobStatus.CANCELLED&&c!=JobStatus.COMPLETED);if(!ok)throw new ConflictException("Invalid status transition: "+c+" -> "+n);j.setStatus(n);return jobs.save(j);}public Bill bill(Long id,double p,double l){JobCard j=get(id);if(j.getStatus()!=JobStatus.COMPLETED)throw new ConflictException("Bill can be generated only for a completed job");Bill b=bills.findByJobCardId(id).orElse(new Bill());b.setJobCard(j);b.setPartsAmount(p);b.setLabourCharge(l);b.setTotalAmount(p+l);return bills.save(b);}}
